#include <iostream>
#include <algorithm>
#include <limits.h>
#include <cstdio>
using namespace std;

int c[6] = {1, 5, 10, 50, 100, 500};

int getNum(int t) {
    int res = 0;
    for (int i = 5; i >= 0; i--) {
        res += t / c[i];
        t %= c[i];
    }
    return res;
}

int main() {
    int P, N[6];
    while (scanf("%d", &P), P) {
        int end = 0;
        for (int i = 0; i < 6; i++) {
            scanf("%d", &N[i]);
            end += c[i] * N[i];
        }
        int ans = INT_MAX;
        for (int i = P; i <= end; i++) {
            int cur = getNum(i - P);
            int l = i;
            for (int j = 5; j >= 0; j--) {
                int available = min(N[j], l / c[j]);
                cur += available;
                l -= available * c[j];
                if (l == 0) break; // Break early if exact amount is reached
            }
            if (l != 0) continue;
            ans = min(ans, cur);
        }
        cout << ans << endl;
    }
}

